<template><div class="office-page"><AppSidebar/><main class="main"><header class="head"><div><h2>公文审批</h2><p>公文起草、两级审批、模板复用与正式发布</p></div><div><el-button @click="load">刷新</el-button><el-button type="primary" @click="openDoc">新建公文</el-button></div></header><el-tabs v-model="tab"><el-tab-pane label="我的公文" name="docs"><el-table :data="docs" size="small" stripe><el-table-column label="公文标题"><template slot-scope="{row}"><button class="link" @click="showDoc(row)">{{row.title}}</button></template></el-table-column><el-table-column prop="document_type" label="类型" width="100"/><el-table-column label="状态" width="100"><template slot-scope="{row}"><el-tag size="mini" :type="tag(row.status)">{{status(row.status)}}</el-tag></template></el-table-column><el-table-column prop="updated_at" label="更新时间" width="170"/><el-table-column label="操作" width="150"><template slot-scope="{row}"><el-button v-if="row.status==='draft'" type="text" @click="submit(row)">提交审批</el-button><el-button v-if="row.status==='approved'" type="text" @click="publish(row)">发布</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="待我审批" name="approval"><el-table :data="approvals" size="small"><el-table-column label="审批事项"><template slot-scope="{row}"><button class="link" @click="showApproval(row)">{{row.title}}</button></template></el-table-column><el-table-column label="状态" width="100"><template slot-scope="{row}"><el-tag size="mini">{{status(row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template slot-scope="{row}"><el-button v-if="row.can_handle" type="success" size="mini" @click="approve(row)">通过</el-button><el-button v-if="row.can_handle" type="danger" size="mini" @click="reject(row)">驳回</el-button><span v-else>无需操作</span></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="模板库" name="templates"><div class="template-bar"><el-alert title="预置通知、周报、会议纪要、请假、报销和采购模板；自建模板支持编辑和删除。" type="info" :closable="false"/><el-button type="primary" size="small" @click="openTemplate">新建模板</el-button></div><el-table :data="templates" size="small" stripe><el-table-column prop="name" label="模板名称"/><el-table-column prop="document_type" label="类型" width="120"/><el-table-column label="来源" width="100"><template slot-scope="{row}">{{row.is_system?'预置':'自建'}}</template></el-table-column><el-table-column label="操作" width="150"><template slot-scope="{row}"><el-button type="text" @click="useTemplate(row)">使用</el-button><el-button v-if="!row.is_system" type="text" @click="editTemplate(row)">编辑</el-button><el-button v-if="!row.is_system" type="text" class="danger" @click="removeTemplate(row)">删除</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></main><el-dialog :title="docForm.id?'编辑公文':'新建公文'" :visible.sync="docVisible" width="680px"><el-form :model="docForm" label-width="80px"><el-form-item label="标题"><el-input v-model="docForm.title"/></el-form-item><el-form-item label="类型"><el-select v-model="docForm.document_type"><el-option label="通知" value="notice"/><el-option label="报告" value="report"/><el-option label="请示" value="request"/></el-select></el-form-item><el-form-item label="正文"><el-input v-model="docForm.content" type="textarea" :rows="12"/></el-form-item></el-form><span slot="footer"><el-button @click="docVisible=false">取消</el-button><el-button type="primary" @click="createDoc">保存草稿</el-button></span></el-dialog><el-dialog title="模板编辑" :visible.sync="templateVisible" width="620px"><el-form :model="templateForm" label-width="80px"><el-form-item label="名称"><el-input v-model="templateForm.name"/></el-form-item><el-form-item label="类型"><el-select v-model="templateForm.document_type"><el-option label="通知" value="notice"/><el-option label="报告" value="report"/><el-option label="请示" value="request"/></el-select></el-form-item><el-form-item label="模板内容"><el-input v-model="templateForm.content" type="textarea" :rows="10"/></el-form-item></el-form><span slot="footer"><el-button @click="templateVisible=false">取消</el-button><el-button type="primary" @click="saveTemplate">保存</el-button></span></el-dialog><el-dialog title="公文详情" :visible.sync="detailVisible" width="680px"><pre>{{detail&&detail.content}}</pre></el-dialog></div></template>
<script>import AppSidebar from '../components/Sidebar/index.vue';export default{components:{AppSidebar},data:()=>({tab:'docs',docVisible:false,templateVisible:false,detailVisible:false,detail:null,docForm:{document_type:'notice'},templateForm:{document_type:'notice'}}),computed:{ws(){return this.$store.getters['workspace/activeWorkspace']||{}},docs(){return this.$store.state.office.documents},approvals(){return this.$store.state.office.approvals},templates(){return this.$store.state.office.templates}},watch:{'ws.id':{immediate:true,handler(){this.load()}}},methods:{load(){if(this.ws.id&&this.ws.domain==='office')return Promise.all(['loadDocuments','loadApprovals','loadTemplates'].map(a=>this.$store.dispatch('office/'+a,this.ws.id)))},openDoc(){this.docForm={document_type:'notice'};this.docVisible=true},async createDoc(){await this.$store.dispatch('office/createDocument',{...this.docForm,workspace_id:this.ws.id});this.docVisible=false;this.load()},useTemplate(t){this.docForm={title:t.name,content:t.content,document_type:t.document_type};this.docVisible=true},openTemplate(){this.templateForm={document_type:'notice'};this.templateVisible=true},editTemplate(t){this.templateForm={...t};this.templateVisible=true},async saveTemplate(){if(this.templateForm.id)await this.$store.dispatch('office/updateTemplate',{id:this.templateForm.id,data:this.templateForm,workspaceId:this.ws.id});else await this.$store.dispatch('office/createTemplate',{...this.templateForm,workspace_id:this.ws.id});this.templateVisible=false},async removeTemplate(t){await this.$confirm('确认删除该模板？');await this.$store.dispatch('office/deleteTemplate',{id:t.id,workspaceId:this.ws.id})},async submit(r){await this.$store.dispatch('office/submitDocument',{id:r.id,data:{},workspaceId:this.ws.id});this.load()},async publish(r){await this.$store.dispatch('office/publishDocument',{id:r.id,workspaceId:this.ws.id});this.load()},async approve(r){await this.$store.dispatch('office/approve',{id:r.id,data:{},workspaceId:this.ws.id});this.load()},async reject(r){try{const x=await this.$prompt('请填写驳回意见','驳回审批');await this.$store.dispatch('office/reject',{id:r.id,data:{comment:x.value},workspaceId:this.ws.id});this.load()}catch(e){}},async showDoc(r){this.detail=await this.$store.dispatch('office/getDocument',r.id);this.detailVisible=true},async showApproval(r){const x=await this.$store.dispatch('office/getApproval',r.id);this.detail=x.document;this.detailVisible=true},status(s){return({draft:'草稿',reviewing:'审批中',approved:'已批准',published:'已发布',pending:'待处理',rejected:'已驳回'})[s]||s},tag(s){return({draft:'info',reviewing:'warning',approved:'success',published:'success'})[s]||''}}}</script><style scoped>.office-page{display:flex;min-height:100vh;padding:12px;gap:12px;background:#f3f6fb}.main{flex:1;padding:20px;background:#fff;border-radius:12px}.head{display:flex;justify-content:space-between;padding-bottom:14px;border-bottom:1px solid #edf0f5}.head h2{margin:0 0 5px}.head p{margin:0;color:#8492a6}.link{border:0;background:none;color:#2875c5;cursor:pointer;font:inherit}.danger{color:#e45b5b}.template-bar{display:flex;gap:10px;align-items:center;margin:4px 0 12px}.template-bar .el-alert{flex:1}pre{white-space:pre-wrap;line-height:1.7;background:#f7f9fc;padding:14px}</style>
